-- Empalmes: número de cliente con dígito verificador (CLIENTE_DV / CLIENTE_FULL del archivo Empalmes.gpkg).
-- Antes solo se guardaba cliente_1 como texto de un número decimal ("2877293.0"; "0.0" = sin cliente) y la app mostraba ese ".0".
-- 1) Columnas nuevas  2) cliente_1 queda como texto limpio (sin ".0"; null si es 0)  3) se completan DV y número completo
-- (el gid de la tabla coincide con el orden de las filas del archivo: verificado fila a fila por N_EMPALMES y cliente)
-- 4) empalmes_en_area entrega también cliente_dv y cliente_full.
alter table public.empalmes add column if not exists cliente_dv text, add column if not exists cliente_full text;

update public.empalmes set cliente_1 = case when cliente_1 ~ '^[0-9]+(\.[0-9]+)?$' and cliente_1::numeric > 0 then round(cliente_1::numeric)::bigint::text end
 where cliente_1 is not null;

update public.empalmes e set cliente_dv = v.dv, cliente_full = v.full_
