create or replace function public.empalmes_en_area(min_lon double precision, min_lat double precision, max_lon double precision, max_lat double precision)
 returns jsonb language sql stable set search_path to 'public' as $$
  select jsonb_build_object(
    'type', 'FeatureCollection',
    'features', coalesce(jsonb_agg(
      jsonb_build_object(
        'type','Feature',
        'geometry', ST_AsGeoJSON(geom)::jsonb,
        'properties', jsonb_build_object(
          'gid', gid, 'n_empalmes', n_empalmes, 'cliente_1', cliente_1, 'cliente_dv', cliente_dv, 'cliente_full', cliente_full
        )
      )
    ), '[]'::jsonb)
  )
  from public.empalmes
  where geom && ST_MakeEnvelope(min_lon,min_lat,max_lon,max_lat,4326)
  limit 3000
$$;
